class Solution {
public:
    string bestHand(vector<int>& ranks, vector<char>& suits) {
        bool flush = true;
        for (int i = 1; i < 5; i++) {
            if (suits[i] != suits[0]) {
                flush = false;
                break;
            }
        }
        if (flush) return "Flush";

        int cnt[14] = {0};
        int maxCnt = 0;
        for (int i = 0; i < 5; i++) {
            cnt[ranks[i]]++;
            if (cnt[ranks[i]] > maxCnt) maxCnt = cnt[ranks[i]];
        }

        if (maxCnt >= 3) return "Three of a Kind";
        if (maxCnt >= 2) return "Pair";
        return "High Card";
    }
};
